/* Famili'Quiz — Nature & Planète */
QUIZ_DATA.add('nature', [
  // ===== Niveau 1 : 7-9 ans =====
  { l: 1, q: "En quelle saison les feuilles de nombreux arbres tombent-elles ?", a: ["L’automne", "Le printemps", "L’été"], e: "🍂🌳", f: "En automne, les arbres arrêtent de nourrir leurs feuilles, qui jaunissent puis tombent." },
  { l: 1, q: "Quel gaz, très utile pour respirer, les plantes rejettent-elles ?", a: ["L’oxygène", "Le gaz carbonique", "L’hélium"], e: "🌿💨", f: "Grâce à la lumière du soleil, les feuilles fabriquent leur nourriture et rejettent de l’oxygène dans l’air." },
  { l: 1, q: "Pendant un orage, que voit-on ou entend-on en premier ?", a: ["L’éclair", "Le tonnerre", "Les deux en même temps"], e: "⛈️👀", f: "La lumière va beaucoup plus vite que le son : on voit l’éclair avant d’entendre le tonnerre." },
  { l: 1, q: "Quel arbre donne des glands ?", a: ["Le chêne", "Le sapin", "Le palmier", "Le pommier"], e: "🌳🐿️", f: "Les glands sont les fruits du chêne. Les écureuils et les geais en enterrent, et certains deviennent de nouveaux chênes !" },
  { l: 1, q: "Comment s’appelle la roche fondue très chaude qui sort d’un volcan ?", a: ["La lave", "La sève", "La craie", "La boue"], e: "🌋🔥", f: "La lave peut dépasser 1 000 °C ! En refroidissant, elle durcit et redevient de la roche." },
  { l: 1, q: "Quelle partie de la plante, cachée sous la terre, puise l’eau ?", a: ["Les racines", "Les pétales", "Les feuilles"], e: "🌱💧", f: "Les racines boivent l’eau et les sels minéraux du sol. Elles tiennent aussi la plante bien accrochée à la terre." },
  { l: 1, q: "On dit souvent que l’arc-en-ciel a combien de couleurs ?", a: ["Sept", "Cinq", "Dix", "Trois"], e: "🌦️🎨", f: "Rouge, orange, jaune, vert, bleu, indigo, violet : en réalité, les couleurs se mélangent sans frontière nette !" },
  { l: 1, q: "Dans beaucoup de villes de France, que met-on dans la poubelle jaune ?", a: ["Les emballages", "Les épluchures", "Les piles"], e: "🗑️💛", f: "Bouteilles en plastique, boîtes de conserve, cartons… Une fois triés, ils seront recyclés en nouveaux objets !" },
  { l: 1, q: "Sur quel arbre pousse la noix de coco ?", a: ["Le cocotier", "Le noyer", "Le pommier", "Le sapin"], e: "🥥🏝️", f: "La noix de coco flotte ! Elle peut voyager sur la mer et germer sur une plage très lointaine." },
  { l: 1, q: "Quelle fleur effeuille-t-on en disant « je t’aime, un peu, beaucoup… » ?", a: ["La marguerite", "La tulipe", "La rose"], e: "💌🌿", f: "Son cœur jaune est en réalité un bouquet de toutes petites fleurs serrées les unes contre les autres." },
  { l: 1, q: "Quelle grande fleur jaune, quand elle est jeune, suit le soleil ?", a: ["Le tournesol", "La rose", "La tulipe", "Le coquelicot"], e: "☀️🌱", f: "Jeune, le tournesol tourne sa tête d’est en ouest avec le soleil. Une fois adulte, il reste tourné vers l’est." },
  { l: 1, q: "Quel arbre garde ses aiguilles l’hiver et sert souvent d’arbre de Noël ?", a: ["Le sapin", "Le chêne", "Le bouleau"], e: "❄️🎁", f: "Le sapin est un conifère : ses aiguilles sont des feuilles très fines qui résistent bien au froid." },
  { l: 1, q: "Que peut-on mettre dans un composteur ?", a: ["Des épluchures de légumes", "Des piles usagées", "Des bouteilles en verre", "Des sacs en plastique"], e: "🥕🍌", f: "Dans le compost, de petites bêtes comme les vers de terre transforment les déchets en terreau pour le jardin." },
  { l: 1, q: "De quoi sont faits les nuages ?", a: ["De minuscules gouttes d’eau", "De fumée de cheminée", "De fils de coton"], e: "☁️🤔", f: "Un nuage contient des milliards de gouttelettes d’eau ou de cristaux de glace, si légers qu’ils flottent dans l’air." },
  { l: 1, q: "De quelle couleur est la fleur du coquelicot ?", a: ["Rouge", "Bleue", "Jaune"], e: "🌾🖍️", f: "Le coquelicot pousse souvent au bord des champs de blé. Ses pétales sont fins comme du papier de soie." },
  { l: 1, q: "Quelle saison commence vers le 21 juin en France ?", a: ["L’été", "L’hiver", "Le printemps", "L’automne"], e: "📅🌍", f: "Vers le 21 juin a lieu le jour le plus long de l’année en France : c’est le solstice d’été." },
  { l: 1, q: "Comment s’appellent les petites graines au cœur d’une pomme ?", a: ["Des pépins", "Des noyaux", "Des glands"], e: "🍎🔍", f: "Chaque pépin est une graine. Planté, il peut donner un pommier… mais ses pommes seront différentes de celles du fruit d’origine !" },
  { l: 1, q: "Comment s’appellent les boules de glace qui tombent pendant certains orages ?", a: ["La grêle", "La neige", "Le givre", "La rosée"], e: "⛈️😮", f: "Les grêlons naissent dans les nuages d’orage, portés par de puissants courants d’air : ils grossissent couche de glace après couche de glace." },
  { l: 1, q: "Quelle plante à piquants pousse bien dans le désert ?", a: ["Le cactus", "La fougère", "Le muguet"], e: "🏜️☀️", f: "Le cactus garde de l’eau dans sa tige épaisse. Ses piquants sont en fait des feuilles transformées !" },
  { l: 1, q: "Quelle partie de la carotte mange-t-on ?", a: ["La racine", "La feuille", "La fleur", "La tige"], e: "🥕🍽️", f: "La carotte est une racine remplie de réserves. Ses feuilles vertes, les fanes, se mangent aussi en soupe !" },
  { l: 1, q: "Le matin, comment s’appellent les gouttes d’eau sur l’herbe ?", a: ["La rosée", "La grêle", "La neige"], e: "🌱🌅", f: "La nuit, l’air se refroidit : sa vapeur d’eau se transforme en gouttelettes sur l’herbe froide." },
  { l: 1, q: "Quelle plante a de grandes feuilles rondes qui flottent sur les étangs ?", a: ["Le nénuphar", "Le lierre", "La marguerite", "Le tournesol"], e: "🐸💧", f: "Les feuilles du nénuphar flottent grâce à l’air qu’elles contiennent. Ses racines sont plantées dans la vase." },
  { l: 1, q: "Quel instrument indique s’il fait chaud ou froid ?", a: ["Le thermomètre", "La boussole", "La loupe"], e: "☀️❄️", f: "Le thermomètre mesure la température en degrés. En France, on utilise les degrés Celsius (°C)." },
  { l: 1, q: "Comment appelle-t-on la forêt chaude et très humide pleine de lianes ?", a: ["La jungle", "La savane", "La toundra", "La banquise"], e: "🌴🐒", f: "Les forêts tropicales abritent une très grande partie des plantes et des animaux de la planète." },
  { l: 1, q: "Comment s’appelle la montée et la descente de la mer, environ deux fois par jour ?", a: ["La marée", "La tempête", "La vague"], e: "🌊🏖️", f: "À marée basse, la mer se retire : on peut alors découvrir des flaques pleines de vie entre les rochers." },
  { l: 1, q: "Quel arbre donne les noix ?", a: ["Le noyer", "Le noisetier", "Le chêne", "Le pin"], e: "🌳❓", f: "La noix est protégée par une coque dure, elle-même entourée d’une enveloppe verte appelée le brou." },
  { l: 1, q: "Que mangent surtout les plantes carnivores ?", a: ["Des insectes", "Des graines", "Des cailloux"], e: "🌿😋", f: "Elles poussent souvent sur des sols pauvres : les insectes leur apportent les éléments nutritifs qui leur manquent." },
  { l: 1, q: "Comment s’appelle un terrain planté d’arbres fruitiers ?", a: ["Un verger", "Un potager", "Une prairie", "Une roseraie"], e: "🍐🍒", f: "Dans un verger, on peut trouver des pommiers, des poiriers, des cerisiers ou des pruniers." },
  { l: 1, q: "Quel arbre produit les pommes de pin ?", a: ["Le pin", "Le pommier", "Le chêne"], e: "🐿️🔍", f: "Les pommes de pin protègent les graines. Elles s’ouvrent quand il fait sec et se referment quand il pleut !" },
  { l: 1, q: "Quand une graine commence à pousser, on dit qu’elle…", a: ["Germe", "Fleurit", "Fane", "Gèle"], e: "💧☀️", f: "Avec de l’eau, de l’air et un peu de chaleur, la graine se réveille : une racine sort, puis une petite tige." },
  { l: 1, q: "Combien y a-t-il de saisons dans une année en France ?", a: ["Quatre", "Deux", "Six"], e: "🗓️🌍", f: "Printemps, été, automne, hiver ! Dans beaucoup de pays tropicaux, on parle plutôt de saison sèche et de saison des pluies." },
  { l: 1, q: "Quel arbre a une écorce blanche qui se détache en fines bandes ?", a: ["Le bouleau", "Le chêne", "Le sapin", "Le noyer"], e: "🌳🤍", f: "Le bouleau résiste très bien au froid : on le trouve jusque dans le Grand Nord, en Laponie." },
  { l: 1, q: "Quelle machine utilise le vent pour fabriquer de l’électricité ?", a: ["L’éolienne", "Le panneau solaire", "Le barrage"], e: "💨⚡", f: "Le vent fait tourner les grandes pales de l’éolienne, qui entraînent une machine produisant de l’électricité." },
  { l: 1, q: "Comment s’appelle un vent très violent qui tourne en forme d’entonnoir ?", a: ["Une tornade", "Une brise", "Une averse", "Une rafale"], e: "💨😮", f: "Une tornade descend d’un gros nuage d’orage. Ses vents tournent très vite, mais elle ne dure souvent que quelques minutes." },
  { l: 1, q: "Quel geste permet d’économiser l’eau ?", a: ["Couper l’eau en se brossant les dents", "Laisser couler le robinet", "Prendre un bain tous les jours"], e: "🚰💧", f: "Une douche rapide utilise beaucoup moins d’eau qu’une baignoire bien remplie." },
  { l: 1, q: "Avant de manger un champignon cueilli en forêt, que faut-il faire ?", a: ["Le montrer à un spécialiste", "Le goûter cru pour tester", "Le sentir très fort"], e: "🍄🌲", f: "Certains champignons sont très toxiques. En France, beaucoup de pharmaciens savent reconnaître les espèces dangereuses." },
  { l: 1, q: "Qu’est-ce qu’un bourgeon ?", a: ["Une future feuille ou fleur", "Un fruit tombé de l’arbre", "Une racine cassée", "Un petit champignon"], e: "🌳🔍", f: "Les bourgeons se forment avant l’hiver. Bien protégés, ils s’ouvrent au printemps pour laisser sortir feuilles et fleurs." },
  { l: 1, q: "De quelle couleur est une émeraude ?", a: ["Verte", "Rouge", "Bleue"], e: "💎❓", f: "L’émeraude est une pierre précieuse très recherchée. Sa belle couleur vient de traces de chrome ou de vanadium." },
  { l: 1, q: "Comment s’appelle une grosse masse de neige qui dévale une montagne ?", a: ["Une avalanche", "Une éruption", "Une averse"], e: "🏔️⚠️", f: "Pour protéger les skieurs, les pisteurs déclenchent parfois exprès de petites avalanches." },
  { l: 1, q: "Quel fruit rouge pousse tout près du sol dans le potager ?", a: ["La fraise", "La cerise", "La pomme", "La prune"], e: "🌱🧺", f: "Les petits grains sur la fraise sont ses vrais fruits : on les appelle des akènes, et chacun contient une graine !" },
  { l: 1, q: "Sur un pommier, qu’est-ce qui apparaît avant les pommes ?", a: ["Des fleurs", "Des glands", "Des épines"], e: "🍎🌳", f: "Au printemps, le pommier se couvre de fleurs blanches et roses. Une fois pollinisée, une fleur peut devenir une pomme." },
  { l: 1, q: "Qui emporte au loin les graines du pissenlit ?", a: ["Le vent", "La pluie", "Les poissons", "La neige"], e: "🌼🪂", f: "Chaque graine de pissenlit a son petit parachute de poils blancs. Le vent peut l’emporter très loin !" },
  { l: 1, q: "Que devient l’eau d’une flaque sous un grand soleil ?", a: ["Elle s’évapore", "Elle gèle", "Elle devient salée"], e: "☀️💧", f: "La chaleur transforme l’eau en vapeur invisible qui monte dans l’air. Plus tard, elle formera des nuages !" },
  { l: 1, q: "Que veut dire le symbole des trois flèches qui tournent en boucle ?", a: ["Recyclable", "Dangereux", "Fragile", "Interdit"], e: "♻️🗑️", f: "Ce symbole indique qu’un emballage peut être recyclé. N’oublie pas de bien le trier !" },
  { l: 1, q: "Comment connaître l’âge d’un arbre qui a été coupé ?", a: ["Compter les cercles du tronc", "Compter ses feuilles", "Mesurer ses racines", "Compter ses branches"], e: "🌳🪓", f: "Chaque année, l’arbre fabrique un nouvel anneau de bois appelé cerne. Un cerne, c’est une année !" },
  { l: 1, q: "Quelle saison vient juste après l’hiver ?", a: ["Le printemps", "L’été", "L’automne"], e: "❄️➡️", f: "Le printemps commence vers le 20 mars. Les jours rallongent et la nature se réveille !" },
  { l: 1, q: "Pour qu’il neige au lieu de pleuvoir, il faut surtout…", a: ["Qu’il fasse froid", "Qu’il y ait du soleil", "Qu’il y ait du vent", "Qu’il fasse nuit"], e: "☁️❄️", f: "Les flocons sont des cristaux de glace. Presque tous ont une forme à six branches !" },
  { l: 1, q: "Quel petit animal transporte le pollen de fleur en fleur ?", a: ["L’abeille", "Le ver de terre", "L’escargot", "La taupe"], e: "🌸🌼", f: "En butinant, l’abeille se couvre de pollen et le dépose sur d’autres fleurs : c’est la pollinisation !" },
  { l: 1, q: "Combien de petites feuilles a un trèfle, la plupart du temps ?", a: ["Trois", "Quatre", "Deux", "Cinq"], e: "🌱🔍", f: "Le trèfle à quatre feuilles existe, mais il est très rare : on dit qu’il porte bonheur !" },
  { l: 1, q: "Comment appelle-t-on une longue période sans pluie ?", a: ["Une sécheresse", "Une inondation", "Une marée"], e: "🏞️☀️", f: "Pendant une sécheresse, les plantes ferment les petits trous de leurs feuilles pour garder leur eau." },

  // ===== Niveau 2 : 10-12 ans =====
  { l: 2, q: "Comment s’appelle le mécanisme qui permet aux plantes de fabriquer leur nourriture grâce à la lumière ?", a: ["La photosynthèse", "La respiration", "La digestion", "La germination"], e: "🌿☀️", f: "Le mot vient du grec : « photo » signifie lumière et « synthèse » veut dire assemblage." },
  { l: 2, q: "Quel nuage géant, souvent en forme d’enclume, provoque les orages ?", a: ["Le cumulonimbus", "Le cirrus", "Le stratus", "L’altocumulus"], e: "⛈️☁️", f: "Un cumulonimbus peut mesurer plus de 10 kilomètres de haut, plus que le mont Everest !" },
  { l: 2, q: "D’où vient principalement le sel de la mer ?", a: ["Des roches lessivées par la pluie", "Du sable fondu par le soleil", "Des algues qui fabriquent du sel"], e: "🌊🧂", f: "Les rivières apportent à la mer des sels arrachés aux roches. L’eau s’évapore, mais le sel, lui, reste !" },
  { l: 2, q: "Quel est le minéral naturel le plus dur ?", a: ["Le diamant", "Le quartz", "Le rubis", "L’or"], e: "💎🔨", f: "Le diamant est si dur qu’on l’utilise dans des outils pour découper le verre, la pierre ou le béton." },
  { l: 2, q: "Quel pigment donne leur couleur verte aux feuilles ?", a: ["La chlorophylle", "La mélanine", "Le carotène", "L’hémoglobine"], e: "🍃🎨", f: "En automne, la chlorophylle disparaît : on voit alors les pigments jaunes et orangés qu’elle cachait." },
  { l: 2, q: "Pour voir un arc-en-ciel, où doit se trouver le soleil ?", a: ["Dans ton dos", "En face de toi", "Juste au-dessus de toi"], e: "🌦️👀", f: "L’arc-en-ciel apparaît du côté opposé au soleil : sa lumière se reflète dans les gouttes de pluie devant toi." },
  { l: 2, q: "Quel arbre produit les châtaignes que l’on mange grillées ?", a: ["Le châtaignier", "Le marronnier", "Le noyer", "Le hêtre"], e: "🌰🔥", f: "Attention : les marrons du marronnier d’Inde ne se mangent pas ! Les « marrons chauds » sont de grosses châtaignes." },
  { l: 2, q: "Quand la vapeur d’eau refroidit et forme des gouttelettes, on parle de…", a: ["Condensation", "Évaporation", "Fusion", "Sublimation"], e: "💧☁️", f: "C’est la condensation qui crée la buée sur un miroir après une douche chaude… et les nuages dans le ciel !" },
  { l: 2, q: "Comment appelle-t-on les arbres comme le pin ou le sapin, qui portent des cônes ?", a: ["Les conifères", "Les feuillus", "Les fruitiers", "Les palmiers"], e: "🌲🌲", f: "« Conifère » veut dire « qui porte des cônes ». La pomme de pin est justement un cône !" },
  { l: 2, q: "Quelle part de l’eau sur Terre est de l’eau douce ?", a: ["Environ 3 %", "Environ 30 %", "Environ 50 %", "Environ 75 %"], e: "🌍💧", f: "Presque toute l’eau de la planète est salée : c’est celle des mers et des océans. L’eau douce est donc précieuse !" },
  { l: 2, q: "Les champignons font-ils de la photosynthèse ?", a: ["Non, ils n’ont pas de chlorophylle", "Oui, comme les plantes vertes", "Oui, mais seulement la nuit"], e: "🍄🌲", f: "Les champignons ne sont ni des plantes ni des animaux : ils forment un groupe à part, le règne des Fungi." },
  { l: 2, q: "Comment s’appelle la roche fondue tant qu’elle se trouve sous la surface de la Terre ?", a: ["Le magma", "La lave", "Le basalte", "Le granite"], e: "🌋⬇️", f: "Le magma prend le nom de « lave » dès qu’il sort à la surface, lors d’une éruption." },
  { l: 2, q: "Quel liquide sucré les fleurs produisent-elles pour attirer les insectes ?", a: ["Le nectar", "Le pollen", "La sève", "La résine"], e: "🌻🐝", f: "Les abeilles transforment le nectar en miel. En échange, elles transportent le pollen d’une fleur à l’autre." },
  { l: 2, q: "Quel appareil enregistre les tremblements de terre ?", a: ["Le sismographe", "Le baromètre", "Le thermomètre", "Le pluviomètre"], e: "🌍〰️", f: "Les sismographes sont si sensibles qu’ils détectent des séismes qui se produisent à l’autre bout de la planète." },
  { l: 2, q: "Dans quelles eaux trouve-t-on surtout les récifs coralliens ?", a: ["Chaudes et peu profondes", "Froides et très profondes", "Glacées, près des pôles"], e: "🐠🌊", f: "Les récifs couvrent moins de 1 % des fonds marins mais abritent environ un quart des espèces marines connues." },
  { l: 2, q: "Le feuillage d’un arbre qui perd ses feuilles chaque hiver est dit…", a: ["Caduc", "Persistant", "Éternel", "Épineux"], e: "🍂🌳", f: "Le hêtre et le bouleau ont un feuillage caduc. Le houx et le pin, eux, gardent leurs feuilles : leur feuillage est persistant." },
  { l: 2, q: "Comment s’appelle le phénomène naturel où certains gaz retiennent la chaleur autour de la Terre ?", a: ["L’effet de serre", "La photosynthèse", "L’érosion", "La condensation"], e: "🌍🌡️", f: "Sans effet de serre naturel, il ferait environ −18 °C en moyenne sur Terre ! C’est son renforcement qui pose problème." },
  { l: 2, q: "Quelle construction utilise la force de l’eau pour produire de l’électricité ?", a: ["Un barrage", "Une éolienne", "Un phare"], e: "💧⚡", f: "L’eau retenue par le barrage descend dans de gros tuyaux et fait tourner des turbines qui produisent l’électricité." },
  { l: 2, q: "Comment s’appelle la forêt qui pousse les pieds dans l’eau salée des côtes tropicales ?", a: ["La mangrove", "La taïga", "La garrigue", "La savane"], e: "🌴🌊", f: "Les palétuviers de la mangrove ont des racines en échasses. Elles protègent les côtes des vagues et des tempêtes." },
  { l: 2, q: "Comment s’appellent les minuscules cellules que libèrent les champignons pour se reproduire ?", a: ["Les spores", "Les pépins", "Les bulbes", "Les ovules"], e: "🍄🔬", f: "Un seul champignon peut libérer des milliards de spores, si légères que le vent les emporte très loin." },
  { l: 2, q: "Que mesure un anémomètre ?", a: ["La vitesse du vent", "La quantité de pluie", "La température", "L’humidité de l’air"], e: "💨📏", f: "L’anémomètre le plus connu porte de petites coupelles qui tournent d’autant plus vite que le vent souffle fort." },
  { l: 2, q: "Laquelle de ces énergies est renouvelable ?", a: ["L’énergie solaire", "Le pétrole", "Le charbon", "Le gaz naturel"], e: "⚡🌍", f: "Le soleil, le vent ou l’eau des rivières ne s’épuisent pas, contrairement au pétrole, au charbon et au gaz." },
  { l: 2, q: "Qu’est-ce que le brouillard ?", a: ["Un nuage qui touche le sol", "De la fumée de cheminée", "De la poussière de sable"], e: "🌫️🚗", f: "Quand on voit à moins d’un kilomètre, les météorologues parlent de brouillard ; au-delà, c’est de la brume." },
  { l: 2, q: "Quel milieu africain est une vaste étendue d’herbes hautes parsemée de quelques arbres ?", a: ["La savane", "La toundra", "La taïga", "La mangrove"], e: "🌾🦒", f: "La savane connaît une saison sèche et une saison des pluies. L’acacia et le baobab y sont des arbres typiques." },
  { l: 2, q: "Quel vêtement peut être fabriqué avec des bouteilles en plastique recyclées ?", a: ["Un pull en polaire", "Un pull en laine", "Une chemise en lin", "Un foulard en soie"], e: "🧥♻️", f: "Broyées puis fondues, les bouteilles en plastique donnent des fils qui servent à fabriquer la laine polaire." },
  { l: 2, q: "Quelle roche volcanique est si légère qu’elle peut flotter sur l’eau ?", a: ["La pierre ponce", "Le granite", "Le marbre", "Le basalte"], e: "🌋💧", f: "La pierre ponce est pleine de petites bulles de gaz, piégées quand la lave a refroidi très vite." },
  { l: 2, q: "Quel arbre détient le record du plus haut arbre du monde ?", a: ["Le séquoia", "Le peuplier", "Le chêne", "Le cèdre"], e: "🌲📏", f: "Le plus haut arbre connu, un séquoia de Californie surnommé Hyperion, mesure plus de 115 mètres !" },
  { l: 2, q: "Quelle couche de gaz de l’atmosphère nous protège des rayons ultraviolets du Soleil ?", a: ["La couche d’ozone", "La couche de nuages", "La couche de pollution"], e: "☀️🛡️", f: "Grâce à un accord mondial signé en 1987, le protocole de Montréal, la couche d’ozone est en train de se reconstituer." },
  { l: 2, q: "Que désigne le mot « biodiversité » ?", a: ["La variété des êtres vivants", "Le recyclage des déchets", "L’étude des volcans", "La protection des océans"], e: "🌿🦋", f: "La biodiversité comprend toutes les espèces, mais aussi leurs différences et les milieux où elles vivent." },
  { l: 2, q: "Quel arbre africain au tronc énorme peut stocker des milliers de litres d’eau ?", a: ["Le baobab", "Le cocotier", "L’acacia", "Le palmier"], e: "🌍🌳", f: "Le baobab peut vivre plus de 1 000 ans. Il perd ses feuilles pendant la saison sèche pour économiser l’eau." },
  { l: 2, q: "Quelle plante peut grandir de près d’un mètre en une seule journée ?", a: ["Le bambou", "Le lierre", "Le cactus", "Le tournesol"], e: "📏⏱️", f: "Certaines espèces de bambou font partie des plantes à la croissance la plus rapide au monde !" },
  { l: 2, q: "Qu’est-ce qui crée la plupart des vagues en mer ?", a: ["Le vent", "La rotation de la Terre", "Les poissons"], e: "🌊🏄", f: "Plus le vent souffle fort, longtemps et sur une grande distance, plus les vagues deviennent hautes." },
  { l: 2, q: "Quand c’est l’été en France, quelle saison est-ce en Australie ?", a: ["L’hiver", "L’été", "Le printemps", "L’automne"], e: "🌏📅", f: "Les saisons sont inversées entre les deux hémisphères. En Australie, on fête Noël en plein été !" },
  { l: 2, q: "Quelle plante grimpante s’accroche aux murs et reste verte toute l’année ?", a: ["Le lierre", "Le houx", "Le gui", "La fougère"], e: "🧱🌿", f: "Ce n’est pas un parasite : ses racines-crampons servent seulement à s’accrocher. Ses fleurs d’automne nourrissent beaucoup d’insectes." },
  { l: 2, q: "Quelle est la source d’énergie qui fait fonctionner le cycle de l’eau ?", a: ["Le Soleil", "Le vent", "La Lune"], e: "🌍💧", f: "La chaleur du Soleil évapore l’eau des océans et des lacs. La pesanteur la fait ensuite retomber en pluie ou en neige." },
  { l: 2, q: "Dans une grotte, comment s’appelle la concrétion qui pend du plafond ?", a: ["La stalactite", "La stalagmite", "La colonne", "La géode"], e: "🦇💧", f: "Astuce : la stalacTite Tombe du plafond, la stalagMite Monte du sol !" },
  { l: 2, q: "Comment s’appelle une source d’eau chaude qui jaillit du sol par intermittence ?", a: ["Un geyser", "Un volcan", "Une cascade", "Un puits"], e: "💨💧", f: "Le mot « geyser » vient de Geysir, une célèbre source jaillissante d’Islande." },
  { l: 2, q: "Pour un botaniste, qu’est-ce que la tomate ?", a: ["Un fruit", "Une racine", "Une tige", "Une feuille"], e: "🍅🔬", f: "En botanique, un fruit vient de la fleur et contient des graines. Le poivron, la courgette et l’avocat sont aussi des fruits !" },
  { l: 2, q: "Comment s’appelle la vague géante provoquée par un séisme sous la mer ?", a: ["Un tsunami", "Un mascaret", "Un cyclone", "Une marée"], e: "🌊🌍", f: "« Tsunami » est un mot japonais qui signifie « vague du port »." },
  { l: 2, q: "Avec quoi fabrique-t-on les bouchons en liège ?", a: ["L’écorce d’un chêne", "Le bois du sapin", "Les racines du bambou"], e: "🍾🌳", f: "On récolte l’écorce du chêne-liège sans abattre l’arbre. Elle repousse et peut être prélevée de nouveau environ tous les 9 ans." },
  { l: 2, q: "Comment appelle-t-on le centre calme d’un cyclone ?", a: ["L’œil", "Le cœur", "Le nez", "Le noyau"], e: "🌀🛰️", f: "Dans l’œil du cyclone, le vent est faible et le ciel parfois dégagé, alors que tout autour soufflent les vents les plus violents." },
  { l: 2, q: "Quelle plante pique la peau grâce à de minuscules poils quand on la frôle ?", a: ["L’ortie", "Le pissenlit", "La menthe", "Le trèfle"], e: "🌿😖", f: "Les poils de l’ortie se cassent comme de minuscules aiguilles et libèrent un liquide irritant. Pourtant, l’ortie se mange en soupe !" },
  { l: 2, q: "Quel métal précieux trouve-t-on parfois en paillettes dans le sable des rivières ?", a: ["L’or", "Le fer", "L’aluminium"], e: "🏞️✨", f: "Les chercheurs d’or, appelés orpailleurs, lavent le sable dans une batée : l’or, très lourd, reste au fond." },
  { l: 2, q: "Quelle plante pousse sur les branches des arbres et décore les maisons au Nouvel An ?", a: ["Le gui", "Le houx", "Le lierre", "Le buis"], e: "🎉🌳", f: "Le gui est une plante semi-parasite : il puise l’eau de l’arbre qui le porte, mais fabrique lui-même sa nourriture." },
  { l: 2, q: "Pourquoi les jardiniers mettent-ils du paillis au pied des plantes ?", a: ["Pour garder le sol humide", "Pour nourrir les mauvaises herbes", "Pour rendre le sol plus salé"], e: "🌱🍂", f: "Le paillis (paille, feuilles, copeaux) limite l’évaporation, protège du froid et empêche les mauvaises herbes de pousser." },
  { l: 2, q: "Quelle est la principale matière première du verre ?", a: ["Le sable", "Le bois", "Le pétrole", "L’argile"], e: "🏖️🔥", f: "Pour fabriquer du verre, on fait fondre du sable à environ 1 500 °C avec d’autres ingrédients." },
  { l: 2, q: "Comment s’appelle une réserve d’eau souterraine contenue dans les roches ?", a: ["Une nappe phréatique", "Un estuaire", "Un delta", "Un glacier"], e: "⬇️💧", f: "En France, environ deux tiers de l’eau potable sont pompés dans les nappes souterraines." },
  { l: 2, q: "Lequel de ces déchets met le plus de temps à disparaître dans la nature ?", a: ["Une bouteille en verre", "Un journal", "Une peau de banane"], e: "🗑️⏳", f: "Le verre peut rester des milliers d’années dans la nature… mais il se recycle à l’infini ! Pense à le trier." },
  { l: 2, q: "Comment s’appelle l’usure lente des roches par l’eau, le vent ou la glace ?", a: ["L’érosion", "L’éruption", "La fusion", "La condensation"], e: "🏜️💨", f: "Grain après grain, l’érosion peut sculpter des falaises, des canyons et des arches de pierre spectaculaires." },
  { l: 2, q: "Quel instrument mesure la pression de l’air pour aider à prévoir le temps ?", a: ["Le baromètre", "L’anémomètre", "Le pluviomètre", "Le sismographe"], e: "🌦️📈", f: "Quand la pression baisse, la pluie arrive souvent ; quand elle remonte, le beau temps revient en général." },

  // ===== Niveau 3 : 13-16 ans =====
  { l: 3, q: "Lors de la photosynthèse, la plante fabrique des sucres à partir de…", a: ["Eau et dioxyde de carbone", "Oxygène et azote", "Glucose et oxygène", "Eau et oxygène"], e: "🌿⚗️", f: "Avec l’énergie lumineuse, la plante transforme l’eau et le CO₂ en glucose, et rejette du dioxygène." },
  { l: 3, q: "Quelle est la cause principale des saisons sur Terre ?", a: ["L’inclinaison de l’axe terrestre", "La distance Terre-Soleil", "Les courants marins", "La rotation de la Lune"], e: "🌍☀️", f: "La Terre est même au plus près du Soleil début janvier, en plein hiver pour l’hémisphère Nord !" },
  { l: 3, q: "Quel conifère perd ses aiguilles chaque automne ?", a: ["Le mélèze", "Le sapin", "L’épicéa", "Le pin"], e: "🌲🍂", f: "Le mélèze est le seul conifère originaire d’Europe à feuillage caduc : ses aiguilles deviennent dorées avant de tomber." },
  { l: 3, q: "Qui a proposé en 1912 la théorie de la dérive des continents ?", a: ["Alfred Wegener", "Charles Darwin", "Louis Pasteur", "Isaac Newton"], e: "🌍🧩", f: "Wegener avait remarqué que les côtes de l’Afrique et de l’Amérique du Sud s’emboîtent comme les pièces d’un puzzle." },
  { l: 3, q: "Comment s’appellent les minuscules pores des feuilles qui permettent les échanges de gaz ?", a: ["Les stomates", "Les vacuoles", "Les nervures", "Les vaisseaux"], e: "🍃🔬", f: "Les stomates s’ouvrent et se ferment selon la lumière et l’humidité. Ils sont souvent plus nombreux sous la feuille." },
  { l: 3, q: "À quelle température un éclair peut-il chauffer l’air qu’il traverse ?", a: ["Environ 30 000 °C", "Environ 3 000 °C", "Environ 800 °C", "Environ 1 million de °C"], e: "⚡🌡️", f: "C’est environ cinq fois plus chaud que la surface du Soleil ! L’air dilaté brutalement produit le grondement du tonnerre." },
  { l: 3, q: "Un lichen est une association entre un champignon et…", a: ["Une algue", "Une mousse", "Une fougère", "Un insecte"], e: "🌳🔍", f: "Beaucoup de lichens ne poussent que là où l’air est peu pollué : ce sont de bons indicateurs de sa qualité." },
  { l: 3, q: "Quelle roche volcanique sombre forme l’essentiel du plancher des océans ?", a: ["Le basalte", "Le granite", "Le calcaire", "Le grès"], e: "🌊🌋", f: "En refroidissant lentement, le basalte forme parfois des colonnes hexagonales, comme à la Chaussée des Géants en Irlande du Nord." },
  { l: 3, q: "Dans quel organite de la cellule végétale se déroule la photosynthèse ?", a: ["Le chloroplaste", "La mitochondrie", "Le noyau", "La vacuole"], e: "🔬🌱", f: "Les chloroplastes descendent d’anciennes bactéries capables de photosynthèse, intégrées dans des cellules il y a très longtemps." },
  { l: 3, q: "Comment s’appelle le sol gelé en permanence des régions arctiques ?", a: ["Le pergélisol", "La banquise", "La toundra", "Le glacier"], e: "❄️🌍", f: "Le pergélisol peut atteindre plusieurs centaines de mètres d’épaisseur. Seule une fine couche de surface dégèle en été." },
  { l: 3, q: "Quelle invention a été inspirée par les fruits crochus de la bardane qui s’accrochent aux poils ?", a: ["Le Velcro", "La fermeture Éclair", "Le bouton-pression", "L’épingle à nourrice"], e: "🐕🌿", f: "Vers 1941, l’ingénieur suisse George de Mestral remarqua ces fruits accrochés au poil de son chien. Il inventa ensuite le « scratch »." },
  { l: 3, q: "Dans quelle couche de l’atmosphère se forment presque tous les nuages ?", a: ["La troposphère", "La stratosphère", "La mésosphère", "La thermosphère"], e: "☁️✈️", f: "C’est la couche la plus basse : elle s’arrête vers 8 km d’altitude au-dessus des pôles et vers 16 km au-dessus de l’équateur." },
  { l: 3, q: "À quelle famille de roches appartient le granite ?", a: ["Les roches magmatiques", "Les roches sédimentaires", "Les roches métamorphiques", "Les roches organiques"], e: "🏔️🔍", f: "Le granite naît du refroidissement lent d’un magma en profondeur : on y voit des cristaux de quartz, de feldspath et de mica." },
  { l: 3, q: "Quelle sève transporte l’eau et les sels minéraux des racines vers les feuilles ?", a: ["La sève brute", "La sève élaborée", "La résine", "Le latex"], e: "🌳💧", f: "La sève élaborée, elle, transporte les sucres fabriqués dans les feuilles vers le reste de la plante." },
  { l: 3, q: "Quel type d’éruption produit surtout des coulées de lave fluide, comme au piton de la Fournaise ?", a: ["Effusive", "Explosive", "Plinienne", "Péléenne"], e: "🌋🏝️", f: "Une lave fluide laisse s’échapper ses gaz et s’écoule en rivières. Une lave visqueuse les piège… jusqu’à l’explosion !" },
  { l: 3, q: "Quelle plante produit la plus grande fleur individuelle du monde, qui peut approcher un mètre de diamètre ?", a: ["Le rafflésia", "Le nénuphar géant", "Le magnolia", "Le tournesol"], e: "🌺📏", f: "Le rafflésia n’a ni tige ni feuilles visibles et dégage une odeur de viande pourrie pour attirer les mouches !" },
  { l: 3, q: "Quel climat se caractérise par des étés chauds et secs et des hivers doux et humides ?", a: ["Le climat méditerranéen", "Le climat océanique", "Le climat continental", "Le climat polaire"], e: "☀️🍇", f: "L’olivier, le chêne vert et la lavande sont bien adaptés à ce climat où l’été peut rester des semaines sans pluie." },
  { l: 3, q: "Comment s’appelle la partie souterraine d’un champignon, formée de longs filaments ?", a: ["Le mycélium", "Le rhizome", "Le tubercule", "Le bulbe"], e: "🍄⬇️", f: "Dans l’Oregon, le mycélium d’un seul champignon s’étend sur près de 10 km² : c’est l’un des plus grands êtres vivants connus !" },
  { l: 3, q: "Quelle échelle classe les minéraux selon leur dureté, de 1 à 10 ?", a: ["L’échelle de Mohs", "L’échelle de Richter", "L’échelle de Beaufort", "L’échelle de Fujita"], e: "💎📏", f: "Le talc est le plus tendre (1) et le diamant le plus dur (10). Ton ongle, lui, a une dureté d’environ 2,5 !" },
  { l: 3, q: "Lequel de ces gaz n’est PAS un gaz à effet de serre ?", a: ["Le diazote (N₂)", "Le méthane", "Le dioxyde de carbone", "La vapeur d’eau"], e: "🌍🧪", f: "Le diazote forme 78 % de l’air mais ne retient pas la chaleur : il n’absorbe pas le rayonnement infrarouge émis par la Terre." },
  { l: 3, q: "Après la fécondation, quelle partie de la fleur se transforme en fruit ?", a: ["L’ovaire", "L’étamine", "Le pétale", "Le sépale"], e: "🌸🍒", f: "L’ovaire se trouve à la base du pistil. Les ovules qu’il contient deviennent les graines du fruit." },
  { l: 3, q: "Comment s’appelle le point de la surface situé juste au-dessus du foyer d’un séisme ?", a: ["L’épicentre", "L’hypocentre", "La faille", "Le cratère"], e: "🌍🎯", f: "Le foyer, ou hypocentre, est l’endroit en profondeur où la roche se rompt. Les dégâts sont souvent les plus forts à l’épicentre." },
  { l: 3, q: "Quelle immense forêt de conifères s’étend au sud de la toundra, en Russie et au Canada ?", a: ["La taïga", "La savane", "La mangrove", "La steppe"], e: "🌲❄️", f: "La taïga, ou forêt boréale, forme le plus vaste ensemble forestier de la planète." },
  { l: 3, q: "Laquelle de ces plantes ne produit ni fleurs ni graines ?", a: ["La fougère", "Le pin", "Le blé", "Le chêne"], e: "🌿🔍", f: "La fougère se reproduit grâce à des spores, souvent visibles en petits amas bruns sous ses feuilles." },
  { l: 3, q: "À quelle vitesse se déplacent en moyenne les plaques tectoniques ?", a: ["Quelques centimètres par an", "Quelques mètres par an", "Quelques kilomètres par an", "Quelques millimètres par siècle"], e: "🌍🐌", f: "C’est à peu près la vitesse à laquelle poussent nos ongles !" },
  { l: 3, q: "Quelle énergie renouvelable utilise la chaleur de l’intérieur de la Terre ?", a: ["La géothermie", "La biomasse", "L’hydraulique", "L’énergie marémotrice"], e: "🌍🔥", f: "En Islande, la géothermie chauffe la grande majorité des logements, et même des serres et des piscines en plein air !" },
  { l: 3, q: "Quels nuages fins, en filaments, sont formés de cristaux de glace très haut dans le ciel ?", a: ["Les cirrus", "Les cumulus", "Les stratus", "Les nimbostratus"], e: "☁️⬆️", f: "Leur nom vient du latin « cirrus », qui signifie boucle de cheveux. Ils annoncent souvent un changement de temps." },
  { l: 3, q: "Dans un écosystème, quels êtres vivants sont les producteurs primaires ?", a: ["Les végétaux chlorophylliens", "Les herbivores", "Les décomposeurs", "Les carnivores"], e: "🌿🔗", f: "Les végétaux fabriquent leur propre matière grâce à la lumière : ils sont à la base de presque toutes les chaînes alimentaires." },
  { l: 3, q: "De quel élément chimique le diamant est-il composé ?", a: ["Le carbone", "Le silicium", "Le calcium", "Le fer"], e: "💎⚗️", f: "Le graphite de nos crayons est lui aussi fait de carbone ! Seule la façon dont les atomes sont rangés change." },
  { l: 3, q: "Comment s’appelle la perte d’eau sous forme de vapeur par les feuilles d’une plante ?", a: ["La transpiration", "La respiration", "La condensation", "La sudation"], e: "🌳💨", f: "Un grand arbre peut rejeter des centaines de litres d’eau par jour : cette vapeur participe à la formation des nuages." },
  { l: 3, q: "Pourquoi l’Antarctique est-il considéré comme un désert ?", a: ["Il y tombe très peu de précipitations", "Il n’y a pas de sable", "Il est inhabité", "Il n’y a aucun arbre"], e: "🧊🏔️", f: "Un désert se définit par sa sécheresse, pas par sa chaleur : l’Antarctique est même le plus grand désert du monde !" },
  { l: 3, q: "Comment appelle-t-on les champignons et bactéries qui recyclent la matière morte du sol ?", a: ["Les décomposeurs", "Les producteurs", "Les pollinisateurs", "Les prédateurs"], e: "🍂🦠", f: "Sans eux, les feuilles mortes s’entasseraient sans fin ! Ils rendent au sol les éléments minéraux utiles aux plantes." },
  { l: 3, q: "De quel minéral sont principalement faites les stalactites des grottes calcaires ?", a: ["La calcite", "Le quartz", "Le gypse", "La glace"], e: "🕳️💧", f: "L’eau de pluie dissout le calcaire des roches puis le redépose, goutte après goutte, en cristaux de calcite. Cela prend des milliers d’années !" },
  { l: 3, q: "Comment s’appelle le vent saisonnier qui apporte de très fortes pluies en Inde en été ?", a: ["La mousson", "Le mistral", "Le sirocco", "L’alizé"], e: "🌧️☂️", f: "« Mousson » vient de l’arabe « mawsim », qui signifie saison. Ses pluies sont essentielles pour les cultures, comme celle du riz." },
  { l: 3, q: "Botaniquement, qu’est-ce qu’une pomme de terre ?", a: ["Un tubercule", "Une racine", "Un bulbe", "Une graine"], e: "🥔🔬", f: "Le tubercule est une tige souterraine gonflée de réserves. Ses « yeux » sont des bourgeons qui peuvent donner de nouvelles pousses." },
  { l: 3, q: "Comment s’appelle la couche sombre du sol, riche en matière organique décomposée ?", a: ["L’humus", "L’argile", "Le sable", "La roche mère"], e: "🌱🟫", f: "L’humus retient l’eau et nourrit les plantes. En forêt, il se forme surtout à partir des feuilles mortes." },
  { l: 3, q: "Comment surnomme-t-on la zone autour de l’océan Pacifique riche en volcans et en séismes ?", a: ["La ceinture de feu", "Le triangle des Bermudes", "La dorsale médio-atlantique", "Le cercle polaire"], e: "🌋🌊", f: "Environ les trois quarts des volcans de la planète se trouvent le long de cette ceinture." },
  { l: 3, q: "Comment s’appelle la plante carnivore dont les feuilles se referment comme une mâchoire ?", a: ["La dionée", "Le népenthès", "Le droséra", "La sarracénie"], e: "🌿🦟", f: "Pour se refermer, la dionée doit sentir deux contacts sur ses poils en peu de temps : cela lui évite de se fermer pour rien." },
  { l: 3, q: "Qu’est-ce qu’un anticyclone ?", a: ["Une zone de hautes pressions", "Une zone de basses pressions", "Un cyclone qui tourne à l’envers", "Un vent chaud venu du désert"], e: "🌤️🗺️", f: "Les anticyclones apportent souvent un temps stable et sec. Celui des Açores influence beaucoup la météo en France." },
  { l: 3, q: "Quelle technique consiste à fixer un morceau d’une plante sur une autre pour qu’ils se soudent ?", a: ["Le greffage", "Le bouturage", "Le marcottage", "Le semis"], e: "🌳✂️", f: "Le greffage permet de reproduire exactement une variété de fruit, ce que les pépins ne permettent pas." },
  { l: 3, q: "Sous quelle forme se trouve la plus grande partie de l’eau douce de la Terre ?", a: ["Glaces et glaciers", "Lacs et rivières", "Nappes souterraines", "Vapeur dans l’atmosphère"], e: "🧊💧", f: "Environ 70 % de l’eau douce est gelée, surtout dans les calottes glaciaires de l’Antarctique et du Groenland." },
  { l: 3, q: "De quel arbre récolte-t-on le latex qui sert à fabriquer le caoutchouc naturel ?", a: ["L’hévéa", "L’acajou", "Le baobab", "Le cocotier"], e: "🎈🌳", f: "On entaille l’écorce de l’hévéa : le latex blanc s’écoule doucement dans une petite tasse fixée au tronc." },
  { l: 3, q: "Quel minéral compose l’essentiel du sable de la plupart des plages ?", a: ["Le quartz", "Le gypse", "Le sel", "Le mica"], e: "🏖️🔍", f: "Très dur, le quartz résiste à l’usure. Mais certaines plages tropicales sont faites de débris de coraux et de coquillages !" },
  { l: 3, q: "Comment s’appelle la croissance d’une plante orientée vers la lumière ?", a: ["Le phototropisme", "La photosynthèse", "Le géotropisme", "La photopériode"], e: "🌱💡", f: "Une plante posée près d’une fenêtre se penche vers la vitre : ses cellules s’allongent davantage du côté ombragé." },
  { l: 3, q: "Quel bois, l’un des plus légers au monde, sert à fabriquer des maquettes ?", a: ["Le balsa", "Le chêne", "L’ébène", "Le teck"], e: "✈️🌳", f: "Le balsa pousse en Amérique tropicale. Il est si léger qu’on l’a utilisé pour construire le célèbre radeau Kon-Tiki !" },
  { l: 3, q: "La nuit, sans lumière, quel gaz les plantes rejettent-elles ?", a: ["Du dioxyde de carbone", "De l’oxygène", "De l’azote", "De l’hydrogène"], e: "🌙🌿", f: "Comme nous, les plantes respirent jour et nuit. Mais le jour, leur photosynthèse produit bien plus d’oxygène qu’elles n’en consomment." },
  { l: 3, q: "Comment appelle-t-on une espèce que l’on ne trouve naturellement que dans une seule région ?", a: ["Une espèce endémique", "Une espèce invasive", "Une espèce disparue", "Une espèce domestique"], e: "🏝️🌺", f: "Les îles abritent beaucoup d’espèces endémiques : à Madagascar, la grande majorité des plantes n’existent nulle part ailleurs." },
  { l: 3, q: "Quel matériau est le plus utilisé dans les cellules des panneaux solaires ?", a: ["Le silicium", "Le cuivre", "Le plomb", "L’uranium"], e: "☀️🔋", f: "Le silicium est le deuxième élément le plus abondant de la croûte terrestre, juste après l’oxygène." },
  { l: 3, q: "En quelle unité exprime-t-on la pression atmosphérique sur les cartes météo ?", a: ["En hectopascals", "En kilowatts", "En décibels", "En nœuds"], e: "📈☁️", f: "La pression moyenne au niveau de la mer est d’environ 1 013 hPa. Quand elle baisse, le mauvais temps approche souvent." },
  { l: 3, q: "Comment appelle-t-on l’ensemble formé par un milieu et tous les êtres vivants qui y vivent ?", a: ["Un écosystème", "Un biotope", "Une biocénose", "Un climat"], e: "🌳🔄", f: "Le biotope désigne le milieu, la biocénose l’ensemble des êtres vivants : réunis, ils forment un écosystème." },

  // ===== Niveau 4 : Adultes =====
  { l: 4, q: "Quel est le gaz à effet de serre le plus abondant dans l’atmosphère terrestre ?", a: ["La vapeur d’eau", "Le dioxyde de carbone", "Le méthane", "L’ozone"], e: "🌍☁️", f: "La vapeur d’eau contribue le plus à l’effet de serre naturel, mais sa quantité dépend surtout de la température de l’air." },
  { l: 4, q: "Comment s’appelle l’association entre les racines d’une plante et un champignon ?", a: ["Une mycorhize", "Un lichen", "Un rhizome", "Une bouture"], e: "🌳🍄", f: "Environ 80 % des plantes terrestres en forment : le champignon apporte eau et minéraux, la plante lui fournit des sucres." },
  { l: 4, q: "Le marbre est une roche métamorphique issue de la transformation de quelle roche ?", a: ["Le calcaire", "Le granite", "Le basalte", "Le grès"], e: "🏛️🔥", f: "Sous l’effet de la chaleur et de la pression, le calcaire recristallise. Michel-Ange sculptait le célèbre marbre blanc de Carrare." },
  { l: 4, q: "Inaugurée en 1966 en Bretagne, l’usine de la Rance produit de l’électricité grâce…", a: ["Aux marées", "Aux vagues", "Au vent", "À la géothermie"], e: "⚡🌊", f: "Ce fut la première grande usine marémotrice au monde. Elle exploite la différence de niveau entre marée haute et marée basse." },
  { l: 4, q: "Comment s’appelait le supercontinent qui réunissait les terres émergées il y a environ 250 millions d’années ?", a: ["La Pangée", "Le Gondwana", "La Laurasia", "La Rodinia"], e: "🗺️⏳", f: "La Pangée a commencé à se fragmenter il y a environ 200 millions d’années, ouvrant peu à peu l’océan Atlantique." },
  { l: 4, q: "Le blé, le maïs, le riz et le bambou appartiennent à quelle famille de plantes ?", a: ["Les graminées", "Les crucifères", "Les ombellifères", "Les composées"], e: "🌾🎋", f: "Le bambou est donc une herbe géante ! Les graminées, ou Poacées, fournissent l’essentiel des céréales qui nourrissent l’humanité." },
  { l: 4, q: "Quels organismes produisent environ la moitié de l’oxygène de la planète ?", a: ["Le phytoplancton", "Les forêts tropicales", "Les prairies", "Les forêts boréales"], e: "🌊🔬", f: "Ces algues microscopiques flottent près de la surface des océans. Elles sont aussi à la base de la chaîne alimentaire marine." },
  { l: 4, q: "Comment s’appelle la végétation basse et parfumée des collines calcaires méditerranéennes ?", a: ["La garrigue", "La lande", "La toundra", "La steppe"], e: "☀️🌿", f: "Thym, romarin et chêne kermès poussent dans la garrigue. Sur sol siliceux, la végétation plus dense s’appelle le maquis." },
  { l: 4, q: "Les coraux qui construisent les récifs vivent en symbiose avec…", a: ["Des algues microscopiques", "Des champignons marins", "Des bactéries du sable", "Des éponges calcaires"], e: "🐠🔬", f: "Ces algues, les zooxanthelles, vivent dans les tissus du corail et le nourrissent grâce à leur photosynthèse. Sans elles, le corail devient tout blanc." },
  { l: 4, q: "Comment appelle-t-on la proportion de lumière solaire réfléchie par une surface ?", a: ["L’albédo", "La réfraction", "L’irradiance", "L’émissivité"], e: "❄️☀️", f: "La neige fraîche réfléchit jusqu’à 90 % de la lumière, alors qu’un océan sombre en absorbe la plus grande partie." },
  { l: 4, q: "À quelle espèce appartient « Mathusalem », l’un des plus vieux arbres vivants, âgé de plus de 4 800 ans ?", a: ["Un pin de Bristlecone", "Un séquoia géant", "Un baobab", "Un olivier"], e: "🌲⏳", f: "Il pousse dans les montagnes de l’est de la Californie. Pour le protéger, son emplacement exact est tenu secret." },
  { l: 4, q: "Pourquoi les légumineuses (pois, trèfle, luzerne) enrichissent-elles le sol ?", a: ["Elles fixent l’azote de l’air", "Elles produisent du calcaire", "Elles rejettent du phosphore", "Elles retiennent le sel"], e: "🌱🧪", f: "Des bactéries logées dans les nodosités de leurs racines transforment l’azote de l’air en engrais naturel." },
  { l: 4, q: "Comment s’appelle le réchauffement périodique des eaux du Pacifique tropical qui perturbe la météo mondiale ?", a: ["El Niño", "La Niña", "Le Gulf Stream", "La mousson"], e: "🌊🌡️", f: "Les pêcheurs péruviens l’ont nommé « l’Enfant », en référence à l’enfant Jésus, car il apparaît souvent vers Noël." },
  { l: 4, q: "Quel arbre, surnommé « fossile vivant », a survécu à la bombe atomique d’Hiroshima ?", a: ["Le ginkgo", "Le platane", "Le tilleul", "Le cèdre"], e: "🍃🕊️", f: "La lignée du ginkgo existait déjà au temps des dinosaures. À Hiroshima, plusieurs ginkgos proches de l’explosion ont refait des pousses." },
  { l: 4, q: "Un séisme de magnitude 7 libère environ combien de fois plus d’énergie qu’un séisme de magnitude 6 ?", a: ["Environ 32 fois", "Environ 2 fois", "Environ 10 fois", "Environ 1 000 fois"], e: "🌍📈", f: "Chaque degré de magnitude multiplie l’amplitude des ondes par 10, mais l’énergie libérée par environ 32 !" },
  { l: 4, q: "Comment s’appelle le vent chaud et sec qui descend le versant d’une montagne ?", a: ["Le foehn", "Le blizzard", "La bise", "L’alizé"], e: "🏔️💨", f: "En redescendant, l’air se comprime et se réchauffe. Le foehn peut faire grimper la température de plus de 10 °C en quelques heures." },
  { l: 4, q: "Pommier, cerisier, fraisier et rosier appartiennent à quelle famille ?", a: ["Les rosacées", "Les solanacées", "Les fabacées", "Les brassicacées"], e: "🍎🍓", f: "Amandier, poirier et framboisier sont aussi des rosacées. Beaucoup de nos fruits sont donc cousins de la rose !" },
  { l: 4, q: "La craie des falaises normandes est formée surtout de…", a: ["Squelettes d’algues microscopiques", "Cendres volcaniques solidifiées", "Sable venu du désert", "Os de dinosaures broyés"], e: "🏞️🔬", f: "Ces algues, les coccolithophoridés, portent des plaques de calcaire. Leurs restes se sont accumulés au fond des mers du Crétacé." },
  { l: 4, q: "Le rubis et le saphir sont deux variétés de quel minéral ?", a: ["Le corindon", "Le béryl", "Le quartz", "La tourmaline"], e: "💍🔍", f: "Le corindon rouge, coloré par le chrome, est un rubis ; toutes les autres couleurs sont des saphirs, le bleu étant le plus connu." },
  { l: 4, q: "Dans l’hémisphère Nord, dans quel sens tournent les vents autour d’une dépression ?", a: ["Sens inverse des aiguilles d’une montre", "Sens des aiguilles d’une montre", "Ils changent de sens chaque jour", "Ils soufflent en ligne droite"], e: "🌀🧭", f: "C’est l’effet de la force de Coriolis, due à la rotation de la Terre. Dans l’hémisphère Sud, c’est l’inverse !" },
  { l: 4, q: "Quels pigments donnent leur couleur rouge aux feuilles d’érable en automne ?", a: ["Les anthocyanes", "Les carotènes", "Les chlorophylles", "Les xanthophylles"], e: "🍁🎨", f: "Contrairement aux pigments jaunes déjà présents, les anthocyanes sont fabriquées en automne, surtout par temps sec et ensoleillé." },
  { l: 4, q: "De quel minerai, nommé d’après un village provençal, extrait-on l’aluminium ?", a: ["La bauxite", "La galène", "L’hématite", "La cassitérite"], e: "⛏️🥫", f: "Son nom vient des Baux-de-Provence, où elle fut découverte en 1821. Recycler l’aluminium économise environ 95 % de l’énergie !" },
  { l: 4, q: "Quel conifère aux petites « baies » rouges a des aiguilles et des graines très toxiques ?", a: ["L’if", "L’épicéa", "Le mélèze", "Le cèdre"], e: "🌲☠️", f: "Seule la chair rouge, l’arille, n’est pas toxique, contrairement à la graine qu’elle entoure. Les ifs peuvent vivre plus de mille ans." },
  { l: 4, q: "Où se forme la nouvelle croûte océanique ?", a: ["Au niveau des dorsales", "Dans les fosses océaniques", "Au centre des continents", "Sous les calottes glaciaires"], e: "⛰️🌊", f: "Le long des dorsales, le magma remonte et refroidit en écartant les plaques. L’Islande est une portion de dorsale émergée !" },
  { l: 4, q: "Comment appelle-t-on la température à partir de laquelle la vapeur d’eau de l’air commence à se condenser ?", a: ["Le point de rosée", "Le point triple", "Le point d’ébullition", "Le zéro absolu"], e: "🌡️💧", f: "Plus il est proche de la température de l’air, plus l’air est humide : brouillard et rosée apparaissent quand les deux se rejoignent." },
  { l: 4, q: "Quel organisme international synthétise les connaissances scientifiques sur le climat ?", a: ["Le GIEC", "L’OMS", "L’UNESCO", "L’OCDE"], e: "📊🌍", f: "Créé en 1988, le GIEC a reçu le prix Nobel de la paix en 2007, avec l’ancien vice-président américain Al Gore." },
  { l: 4, q: "Quelle roche volcanique noire et vitreuse était taillée en lames tranchantes à la préhistoire ?", a: ["L’obsidienne", "Le basalte", "La pierre ponce", "Le silex"], e: "🌋🔪", f: "L’obsidienne est un verre naturel formé par une lave refroidie très vite. Ses éclats peuvent être plus tranchants qu’un scalpel d’acier !" },
  { l: 4, q: "Comment s’appelle le tube de verre naturel formé quand la foudre frappe le sable ?", a: ["Une fulgurite", "Une géode", "Une concrétion", "Une stalagmite"], e: "⚡🏖️", f: "Son nom vient du latin « fulgur », la foudre. Ces tubes creux et fragiles s’enfoncent parfois de plusieurs mètres dans le sol." },
  { l: 4, q: "Dans un double arc-en-ciel, qu’a de particulier le second arc ?", a: ["Ses couleurs sont inversées", "Il est plus lumineux", "Il est situé sous le premier", "Il n’a que trois couleurs"], e: "🌈🌈", f: "Il naît d’une double réflexion dans les gouttes. Entre les deux arcs, le ciel paraît plus sombre : c’est la bande d’Alexandre." },
  { l: 4, q: "Pourquoi la neige est-elle blanche alors que la glace est transparente ?", a: ["Ses cristaux diffusent la lumière", "Elle contient de l’air coloré", "Elle contient du sel", "Elle est bien plus froide"], e: "❄️🔦", f: "Les innombrables facettes des cristaux renvoient la lumière dans tous les sens, sans privilégier de couleur : on voit donc du blanc." },
  { l: 4, q: "Ouragan, typhon et cyclone tropical désignent…", a: ["Le même phénomène selon la région", "Trois intensités de tempête", "Trois types de tornades", "Des vents de saisons différentes"], e: "🌀🌊", f: "On parle d’ouragan dans l’Atlantique, de typhon dans le Pacifique nord-ouest et de cyclone dans l’océan Indien." },
  { l: 4, q: "Botaniquement, le bananier est…", a: ["Une herbe géante", "Un arbre", "Un palmier", "Une liane"], e: "🍌🌴", f: "Son « tronc » est formé de gaines de feuilles enroulées les unes sur les autres. C’est l’une des plus grandes plantes herbacées du monde." },
  { l: 4, q: "Lequel de ces « fruits secs » se développe sous la terre ?", a: ["L’arachide", "La noisette", "L’amande", "La noix de cajou"], e: "🌱⬇️", f: "Après la floraison, un pédoncule de la fleur d’arachide s’allonge et enfonce le jeune fruit dans le sol, où mûrit la gousse." },
  { l: 4, q: "Quelle plante du désert du Namib peut vivre plus de mille ans avec seulement deux feuilles ?", a: ["Le welwitschia", "Le baobab", "L’agave", "Le saguaro"], e: "🏜️🌿", f: "Ses deux feuilles poussent sans jamais s’arrêter. Déchirées par le vent, elles donnent l’impression d’être nombreuses." },
  { l: 4, q: "Les spirales de graines d’un cœur de tournesol suivent souvent une suite mathématique célèbre. Laquelle ?", a: ["La suite de Fibonacci", "La suite de Syracuse", "La suite de Conway", "La suite de Cauchy"], e: "🌻🔢", f: "On y compte souvent 34 et 55 spirales, ou 55 et 89 : des nombres consécutifs de la suite de Fibonacci (1, 1, 2, 3, 5, 8…)." },
  { l: 4, q: "Comment s’appelle une zone humide où les végétaux morts s’accumulent sans se décomposer complètement ?", a: ["Une tourbière", "Une mangrove", "Une garrigue", "Une lande"], e: "💧🌿", f: "Les tourbières ne couvrent qu’environ 3 % des terres émergées, mais comptent parmi les plus grands réservoirs de carbone de la planète." },
  { l: 4, q: "La « rose des sables » du Sahara est un assemblage de cristaux de…", a: ["Gypse", "Quartz", "Sel gemme", "Calcite"], e: "🏜️🌹", f: "Elle se forme quand l’eau d’une nappe souterraine s’évapore : le gypse cristallise en pétales en emprisonnant des grains de sable." },
  { l: 4, q: "Quelle méthode de culture s’inspire du fonctionnement des écosystèmes naturels pour être durable ?", a: ["La permaculture", "La culture sous serre", "La monoculture", "L’agriculture intensive"], e: "🌱🔄", f: "Le mot, inventé dans les années 1970 par les Australiens Bill Mollison et David Holmgren, vient de « permanent agriculture »." },
  { l: 4, q: "Comment appelle-t-on la culture de plantes hors sol, les racines plongées dans une solution nutritive ?", a: ["L’hydroponie", "L’aéroponie", "Le bouturage", "Le marcottage"], e: "💧🌱", f: "Cette technique économise l’eau et permet de cultiver salades ou tomates dans des fermes verticales, en pleine ville." },
  { l: 4, q: "Quel phénomène, observé sur une plante aquatique, inspire des surfaces autonettoyantes ?", a: ["L’effet lotus", "L’effet Venturi", "L’effet Doppler", "L’effet Coriolis"], e: "💧🌸", f: "Grâce à de minuscules reliefs cireux, l’eau perle sur la feuille de lotus et emporte la poussière en roulant." },
  { l: 4, q: "Comment appelle-t-on l’odeur caractéristique de la terre après la pluie ?", a: ["Le pétrichor", "Le patchouli", "Le serein", "Le muscat"], e: "🌧️👃", f: "Elle vient en partie de la géosmine, une molécule produite par des bactéries du sol, que notre nez détecte à très faible dose." },
  { l: 4, q: "Comment appelle-t-on les marées de plus forte amplitude, à la pleine et à la nouvelle lune ?", a: ["Les vives-eaux", "Les mortes-eaux", "Les eaux de crue", "Les eaux d’étiage"], e: "🌊🌕", f: "La Lune et le Soleil sont alors alignés et leurs attractions s’additionnent. Les plus fortes ont lieu près des équinoxes." },
  { l: 4, q: "Comment s’appelle la vague qui remonte certains fleuves lors des grandes marées ?", a: ["Le mascaret", "Le ressac", "La houle", "Le clapot"], e: "🏞️🌊", f: "En France, on peut l’observer sur la Dordogne et la Garonne. Des surfeurs le chevauchent parfois sur plusieurs kilomètres !" },
  { l: 4, q: "Quels organismes ont enrichi l’atmosphère en oxygène il y a plus de 2 milliards d’années ?", a: ["Les cyanobactéries", "Les fougères", "Les champignons", "Les premiers arbres"], e: "🦠⏳", f: "Ces bactéries capables de photosynthèse ont bâti les stromatolithes, des roches en couches qu’on trouve encore en Australie." },
  { l: 4, q: "Quelle période géologique doit son nom aux immenses gisements de charbon formés par ses forêts ?", a: ["Le Carbonifère", "Le Jurassique", "Le Crétacé", "Le Trias"], e: "🌿⛏️", f: "Il y a 300 à 360 millions d’années, de vastes forêts de fougères arborescentes et de prêles géantes ont été enfouies puis changées en charbon." },
  { l: 4, q: "Quelle science permet de dater le bois grâce aux cernes de croissance des arbres ?", a: ["La dendrochronologie", "La palynologie", "La glaciologie", "La stratigraphie"], e: "🌳🔬", f: "En comparant les cernes de bois anciens, les chercheurs ont bâti des calendriers qui remontent à plus de 10 000 ans !" },
  { l: 4, q: "Quelle science étudie la formation et l’évolution des sols ?", a: ["La pédologie", "La pédiatrie", "La géodésie", "La sismologie"], e: "🌱🔍", f: "Le mot vient du grec « pedon », le sol. Il faut souvent des siècles pour former quelques centimètres de sol fertile." },
  { l: 4, q: "Il y a environ 6 000 ans, à quoi ressemblait une grande partie du Sahara ?", a: ["À une savane parsemée de lacs", "À une forêt de conifères", "À une calotte de glace", "À un bras de mer"], e: "🏜️⏳", f: "Durant cette « période humide africaine », girafes et hippopotames y vivaient, comme le montrent de nombreuses peintures rupestres." },
  { l: 4, q: "Lors du dernier maximum glaciaire, il y a environ 20 000 ans, le niveau des mers était…", a: ["Environ 120 m plus bas", "Environ 10 m plus bas", "Environ 50 m plus haut", "Identique à aujourd’hui"], e: "🧊🌊", f: "On pouvait alors traverser la Manche à pied, ou passer d’Asie en Amérique par le détroit de Béring !" },
  { l: 4, q: "Quelle plante à fleurs, et non une algue, forme de vastes herbiers sous-marins en Méditerranée ?", a: ["La posidonie", "La laminaire", "Le varech", "La caulerpe"], e: "🌊🌿", f: "La posidonie oxygène l’eau et abrite de nombreux poissons. Ses débris fibreux forment les « pelotes de mer » échouées sur les plages." }
]);
